INSERT INTO "Actividad" ("nivelId", "clave", "titulo", "descripcion", "objetivo", "minutos", "juego", "reglas", "ejemplo", "orden") VALUES ((SELECT "id" FROM "Nivel" WHERE "seccion" = '1' AND "clave" = '2'), '1', 'Ordena los pasos', 'Una tarea de todos los días tiene sus pasos revueltos: déjalos en el orden en que se hacen.', 'Ordenar los pasos de una tarea según lo que depende de qué.', 3, 'ordenar', '["Verás los pasos de una tarea cotidiana en desorden.","Usa las flechas de cada paso para subirlo o bajarlo hasta dejar el orden correcto.","Pulsa «Comprobar el orden». Si te equivocas pierdes una vida y se te explica qué paso depende de cuál.","Puedes pedir hasta 3 pistas por ronda; no cuentan como error ni dan puntos."]'::jsonb, '{"secuencia":["Hablar con la persona","Marcar el número","Tomar el teléfono"],"respuesta":["Tomar el teléfono","Marcar el número","Hablar con la persona"],"explicacion":"No puedes marcar sin tener el teléfono en la mano, ni hablar sin haber marcado: cada paso necesita el anterior."}'::jsonb, 0) ON CONFLICT ("nivelId", "clave") DO NOTHING;
INSERT INTO "Actividad" ("nivelId", "clave", "titulo", "descripcion", "objetivo", "minutos", "juego", "reglas", "ejemplo", "orden") VALUES ((SELECT "id" FROM "Nivel" WHERE "seccion" = '1' AND "clave" = '2'), '2', 'Completa las instrucciones', 'A una lista de instrucciones le falta un paso: elige el que encaja entre el anterior y el siguiente.', 'Deducir el paso que falta en una secuencia de instrucciones.', 3, 'instrucciones', '["Verás las instrucciones de una tarea con un hueco en el medio.","Elige, entre las opciones, el paso que va en el hueco; ojo, no todas pertenecen a la tarea.","Pulsa «Comprobar». Si te equivocas pierdes una vida y se te explica por qué ese paso no encaja.","Puedes pedir hasta 3 pistas por ronda; no cuentan como error ni dan puntos."]'::jsonb, '{"secuencia":["Tomar el teléfono","❔","Hablar con la persona"],"resaltar":1,"respuesta":["Marcar el número"],"explicacion":"Entre tomar el teléfono y hablar hace falta marcar el número: sin él nadie contesta."}'::jsonb, 1) ON CONFLICT ("nivelId", "clave") DO NOTHING;
INSERT INTO "Actividad" ("nivelId", "clave", "titulo", "descripcion", "objetivo", "minutos", "juego", "reglas", "ejemplo", "orden") VALUES ((SELECT "id" FROM "Nivel" WHERE "seccion" = '1' AND "clave" = '2'), '3', 'Ejecuta el algoritmo', 'Sigue una lista corta de instrucciones, una por una, y averigua con qué número terminas.', 'Ejecutar a mano un algoritmo corto y obtener su resultado.', 4, 'ejecutar', '["Empiezas con un número y una lista de instrucciones.","Aplícalas de arriba hacia abajo, una a la vez, y fíjate en el valor después de cada una.","Elige con qué número terminas y pulsa «Comprobar». Si te equivocas pierdes una vida y se te dice qué error parece haber pasado.","Puedes pedir hasta 3 pistas por ronda; no cuentan como error ni dan puntos."]'::jsonb, '{"secuencia":["Empieza con 3","Suma 2","Duplica el valor"],"respuesta":["10"],"explicacion":"3 y suma 2 es 5; duplicar 5 da 10. Si cambias el orden, el resultado cambia."}'::jsonb, 2) ON CONFLICT ("nivelId", "clave") DO NOTHING;
